const Hyperswarm = require('hyperswarm')

module.exports = device_network

// finds my other devices on the dht by the settings discovery key and replicates the whole store with them.
// only devices that have the keys can replicate, and the settings are encrypted
function device_network ({ store, bootstrap }) {
  const state = { swarm: null }
  const api = { start, join, stop, get swarm () { return state.swarm } }
  return api

  async function start () {
    state.swarm = new Hyperswarm({ keyPair: await store.createKeyPair('hyperswarm'), bootstrap })
    state.swarm.on('connection', socket => store.replicate(socket))
    return state.swarm
  }
  function join (discovery_key) { return state.swarm.join(discovery_key) }
  async function stop () { if (state.swarm) await state.swarm.destroy() }
}
